<script setup lang="ts">
import {computed,reactive,ref} from 'vue';import PageHeader from '../../components/common/PageHeader.vue';import SegmentTabs from '../../components/common/SegmentTabs.vue';import EmptyState from '../../components/common/EmptyState.vue';import DetailDrawer from '../../components/common/DetailDrawer.vue';import StatusTag from '../../components/common/StatusTag.vue';import {workbenchRepository} from '../../services/workbenchRepository';
const data=ref(workbenchRepository.load());const mainTab=ref('okr');const category=ref('my');const cycle=ref('2026-09');const formOpen=ref(false);const reviewOpen=ref(false);const form=reactive({objective:'',weight:'',deadline:'',alignTo:'',kr:''});const review=reactive({cycleName:'',type:'',summary:'',selfScore:''});
const visible=computed(()=>data.value.okrs.filter(item=>item.cycle===cycle.value&&item.category===category.value));const persist=()=>workbenchRepository.save(data.value);const reset=()=>Object.assign(form,{objective:'',weight:'',deadline:'',alignTo:'',kr:''});
const addOkr=()=>{if(!form.objective||!form.deadline)return;data.value.okrs.unshift({id:`OKR-${Date.now()}`,cycle:cycle.value,category:'my',objective:form.objective,owner:'当前用户',progress:0,weight:Number(form.weight)||0,deadline:form.deadline,alignTo:form.alignTo,keyResults:form.kr?[{id:`KR-${Date.now()}`,content:form.kr,progress:0,weight:100,deadline:form.deadline}]:[]});persist();formOpen.value=false;reset()};
const addReview=()=>{if(!review.cycleName||!review.type||!review.summary)return;data.value.reviews.unshift({id:`REV-${Date.now()}`,cycleName:review.cycleName,type:review.type as '周复盘'|'月复盘',summary:review.summary,selfScore:Number(review.selfScore)||0,status:'已提交',createdAt:new Date().toISOString().slice(0,10)});persist();reviewOpen.value=false;Object.assign(review,{cycleName:'',type:'',summary:'',selfScore:''})};
</script>
<template><section class="workbench-view"><PageHeader eyebrow="OKR & PERFORMANCE" title="目标与绩效" description="管理目标、关键结果以及周期复盘。"><template #actions><select v-model="cycle"><option value="2026-09">2026年09月</option><option value="2026-08">2026年08月</option></select><button v-if="mainTab==='okr'" class="primary" @click="formOpen=true">添加目标</button><button v-else class="primary" @click="reviewOpen=true">写复盘</button></template></PageHeader><SegmentTabs v-model="mainTab" :items="[{key:'okr',label:'目标管理'},{key:'review',label:'复盘总结',count:data.reviews.length}]"/><template v-if="mainTab==='okr'"><SegmentTabs v-model="category" :items="[{key:'my',label:'我的 OKR'},{key:'supervisor',label:'直属上级'},{key:'subordinate',label:'直属下级'},{key:'department',label:'本部门'},{key:'other',label:'跨部门'}]"/><div v-if="visible.length" class="okr-list"><article v-for="okr in visible" :key="okr.id" class="panel"><div class="okr-title"><div><StatusTag :status="`${okr.progress}%`"/><h3>{{okr.objective}}</h3><small>{{okr.owner}} · 截止 {{okr.deadline}} · 权重 {{okr.weight}}%</small></div><strong>{{okr.progress}}%</strong></div><p v-if="okr.alignTo" class="muted">对齐：{{okr.alignTo}}</p><div class="progress"><i :style="{width:`${okr.progress}%`}"/></div><div class="kr-grid"><div v-for="(kr,index) in okr.keyResults" :key="kr.id"><strong>KR{{index+1}} {{kr.content}}</strong><span>{{kr.progress}}%</span><div class="progress small"><i :style="{width:`${kr.progress}%`}"/></div></div></div></article></div><EmptyState v-else title="当前分类暂无目标" description="可切换分类或添加新的目标。"/></template><div v-else class="panel"><div v-if="data.reviews.length" class="stack-list"><div v-for="item in data.reviews" :key="item.id" class="list-row static"><span><strong>{{item.cycleName}}</strong><small>{{item.type}} · {{item.createdAt}} · 自评 {{item.selfScore}} 分</small><p>{{item.summary}}</p></span><StatusTag :status="item.status"/></div></div><EmptyState v-else title="暂无复盘记录"/></div><DetailDrawer :open="formOpen" title="添加目标" @close="formOpen=false"><form class="work-item-form" @submit.prevent="addOkr"><label>目标名称<input v-model="form.objective" required placeholder="请输入目标名称"/></label><label>对齐目标<input v-model="form.alignTo" placeholder="请选择或输入对齐目标"/></label><div class="form-grid"><label>目标权重<input v-model="form.weight" type="number" min="0" max="100" placeholder="请输入权重"/></label><label>截止日期<input v-model="form.deadline" required type="date"/></label></div><label>关键结果<textarea v-model="form.kr" rows="4" placeholder="请输入可衡量的关键结果"/></label><div class="form-actions"><button type="button" class="secondary" @click="formOpen=false">取消</button><button class="primary">提交</button></div></form></DetailDrawer><DetailDrawer :open="reviewOpen" title="填写复盘总结" @close="reviewOpen=false"><form class="work-item-form" @submit.prevent="addReview"><label>周期名称<input v-model="review.cycleName" required placeholder="请输入复盘周期名称"/></label><label>复盘类型<select v-model="review.type" required><option value="" disabled>请选择复盘类型</option><option>周复盘</option><option>月复盘</option></select></label><label>核心工作总结<textarea v-model="review.summary" required rows="5" placeholder="请输入本周期工作成果与改进计划"/></label><label>自评得分<input v-model="review.selfScore" type="number" min="0" max="100" placeholder="请输入0-100分"/></label><div class="form-actions"><button type="button" class="secondary" @click="reviewOpen=false">取消</button><button class="primary">提交复盘</button></div></form></DetailDrawer></section></template>
